mapper.select:
with p as ( select db_id, table_id, sum(if(status='INIT', 1, 0)) as init, sum(if(status='DOING', 1, 0)) as doing, sum(if(status='DONE', 1, 0)) as done, sum(if(status='FAILED', 1, 0)) as failed, count(*) as partitions from partition_model where source_id=#{sourceId} group by db_id, table_id ), t as ( select table_model.db_id as db_id, ( case when has_partitions = 0 or p.partitions = 0 then status when p.doing > 0 then 'DOING' when p.failed > 0 then 'FAILED' when p.done = p.partitions then 'DONE' when p.done > 0 and p.done < p.partitions then 'PART_DONE' else 'INIT' end ) as status from table_model left join p on table_model.id = p.table_id where source_id=#{sourceId} ), dp as ( select db_id, sum(init) as init, sum(doing) as doing, sum(done) as done, sum(failed) as failed, sum(partitions) as partitions from p group by db_id ), dt as ( select db_id, sum(if(status='INIT', 1, 0)) as init, sum(if(status='DOING', 1, 0)) as doing, sum(if(status='DONE', 1, 0)) as done, sum(if(status='FAILED', 1, 0)) as failed, sum(if(status='PART_DONE', 1, 0)) as part_done, count(*) as tables from t group by db_id ), ddp as ( select id, name, source_id, db_model.num_rows as num_rows, db_model.size as size, dp.partitions as partitions, dp.done as partitionsDone, dp.doing as partitionsDoing, dp.failed as partitionsFailed from db_model left join dp on db_model.id = dp.db_id where source_id = #{sourceId}
and db_model.id = #{id}
and `name` like CONCAT('%', #{name}, '%')
) select ddp.*, dt.tables as tables, dt.done as tablesDone, dt.part_done as tablesPartDone, dt.doing as tablesDoing, dt.failed as tablesFailed from ddp left join dt on ddp.id = dt.db_id
${p.name} ${p.order}
limit #{offset}, #{pageSize}

select count(*) from db_model



        source_id =#{sourceId}



        and id = #{id}



        and `name` like CONCAT('%', #{name}, '%')
